using System.Text.Encodings.Web;
namespace Aegis.Diagnostics;
internal static class SuiteLoginPage
{
    public static string Render(string product,string mode,string? ret)
    {
        string p=HtmlEncoder.Default.Encode(product),m=HtmlEncoder.Default.Encode(mode),r=HtmlEncoder.Default.Encode(ret??"/");
        string html="""<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>System __PRODUCT__ Sign In</title><style>html,body{margin:0;min-height:100%;font-family:'Segoe UI',Arial;background:radial-gradient(circle at 50% -10%,#17466c,#041827 42%,#000910);color:#eef6ff}.top{height:90px;background:linear-gradient(#092b46,#00111f);border-bottom:2px solid #4180aa;display:flex;align-items:center;padding:0 35px}.bars{display:flex;gap:7px;margin-right:18px}.bars i{width:28px;height:55px;background:linear-gradient(#ffd47b,#ffae31,#d36d00);box-shadow:inset 0 2px #fff8,0 0 15px #ffad3155}.bars i:last-child{background:linear-gradient(#b99aff,#8e61ff,#5430bd)}h1{font-size:34px;margin:0}h1 em{font-style:normal;color:#ffc25c}.sub,.org{color:#42bdff;font-weight:800}.org{margin-left:auto}.shell{max-width:1120px;margin:45px auto;border:1px solid #4f9bc8;border-radius:26px;box-shadow:inset 0 0 38px #34b0ff22,0 10px 30px #0009;display:grid;grid-template-columns:190px 1fr;overflow:hidden;min-height:520px}.rail{background:linear-gradient(90deg,#00111e,#052943);padding-top:60px}.rail div{height:52px;margin:8px 0;background:linear-gradient(#d8caff,#9e8cff,#6250bf);border-radius:0 25px 25px 0}.rail div:nth-child(2){width:80%;background:linear-gradient(#ffd47b,#ffb13c,#c96b00)}.rail div:nth-child(3){width:65%;background:linear-gradient(#d4f2ff,#78caff,#3983bd)}.content{padding:65px 9vw;background:linear-gradient(145deg,#082c47ee,#001522f7 55%,#000c16)}.content h2{font-size:30px;margin:0}.content p{color:#b9cfe0}.mode{display:inline-block;color:#71efad;border:1px solid #238d67;background:#063d2b;padding:5px 10px;border-radius:5px;margin:10px 0 24px}label{display:block;color:#6dc9ff;margin:13px 0 5px}input{width:100%;padding:13px;background:linear-gradient(#0c3553,#031d31);border:1px solid #317cab;border-radius:6px;color:white;font-size:16px;box-sizing:border-box}button{width:100%;margin-top:25px;padding:14px;border:1px solid #ffd36d;border-radius:7px;background:linear-gradient(#ffd77d,#ff9f16,#b65c00);font-weight:900;font-size:16px}@media(max-width:700px){.org{display:none}.shell{margin:10px;grid-template-columns:60px 1fr}.content{padding:45px 24px}h1{font-size:23px}}</style></head><body><header class="top"><div class="bars"><i></i><i></i></div><div><h1>System <em>__PRODUCT__</em></h1><div class="sub">SECURE SYSTEM ACCESS</div></div><div class="org">Food For The Poor Jamaica<br>A More Hopeful Tomorrow</div></header><section class="shell"><aside class="rail"><div></div><div></div><div></div></aside><main class="content"><h2>Sign in to System __PRODUCT__</h2><p>Direct access uses the configured authentication provider. Access from Operations uses a secure handoff automatically.</p><span class="mode">__MODE__ authentication</span><form method="post" action="/auth/login"><input type="hidden" name="returnUrl" value="__RETURN__"><label>Username</label><input name="username" autocomplete="username" required autofocus><label>Password</label><input type="password" name="password" autocomplete="current-password" required><button>AUTHENTICATE →</button></form></main></section></body></html>""";
